import{_ as e,c as t,o,a2 as r}from"./chunks/framework.DgH2I27U.js";const f=JSON.parse('{"title":"Git GitHub Flow","description":"","frontmatter":{},"headers":[],"relativePath":"fr/github/github-flow.md","filePath":"fr/github/github-flow.md"}'),a={name:"fr/github/github-flow.md"},i=r('<h1 id="git-github-flow" tabindex="-1">Git GitHub Flow <a class="header-anchor" href="#git-github-flow" aria-label="Permalink to &quot;Git GitHub Flow&quot;">​</a></h1><h2 id="travailler-avec-github-flow" tabindex="-1">Travailler avec GitHub Flow <a class="header-anchor" href="#travailler-avec-github-flow" aria-label="Permalink to &quot;Travailler avec GitHub Flow&quot;">​</a></h2><p>Dans cette section, vous apprendrez comment tirer le meilleur parti de l&#39;utilisation de GitHub.</p><p>Le <strong>GitHub Flow</strong> est un flux de travail conçu pour bien fonctionner avec Git et GitHub. Il met l&#39;accent sur la gestion des branches et permet aux équipes de tester librement leurs idées et de déployer régulièrement leurs projets.</p><p>Le processus du GitHub Flow se déroule comme suit :</p><ol><li>Créer une nouvelle branche</li><li>Apporter des modifications et ajouter des commits</li><li>Ouvrir une Pull Request</li><li>Effectuer une revue des modifications</li><li>Déployer les modifications</li><li>Fusionner les changements dans la branche principale</li></ol><p>Vous devez déjà avoir une bonne compréhension de ce fonctionnement grâce aux chapitres précédents. Ce chapitre se concentre sur la façon dont le flux de travail facilite la collaboration.</p><h2 id="demonstration-de-git-workflow" tabindex="-1">Démonstration de git workflow <a class="header-anchor" href="#demonstration-de-git-workflow" aria-label="Permalink to &quot;Démonstration de git workflow&quot;">​</a></h2><p><img src="https://custom-images.strikinglycdn.com/res/hrscywv4p/image/upload/c_limit,fl_lossy,h_9000,w_1200,f_auto,q_auto/784839/565740_955421.png" alt="git workflow"></p><h2 id="creer-une-nouvelle-branche" tabindex="-1">Créer une nouvelle branche <a class="header-anchor" href="#creer-une-nouvelle-branche" aria-label="Permalink to &quot;Créer une nouvelle branche&quot;">​</a></h2><p>Les <strong>branches</strong> sont un concept clé de Git. Elles fonctionnent selon la règle suivante : la branche principale (souvent appelée <code>master</code> ou <code>main</code>) doit toujours être <strong>déployable</strong>.</p><p>Cela signifie que si vous souhaitez tester une nouvelle fonctionnalité ou effectuer une expérience, vous créez une nouvelle branche ! La création de branches vous offre un environnement sécurisé pour apporter des modifications sans affecter la branche principale.</p><h3 id="bonne-pratique" tabindex="-1">Bonne pratique : <a class="header-anchor" href="#bonne-pratique" aria-label="Permalink to &quot;Bonne pratique :&quot;">​</a></h3><p>Lorsque vous créez une nouvelle branche, il est préférable de partir de la branche principale (<code>master</code> ou <code>main</code>). Assurez-vous que le nom de la branche soit descriptif, afin que toute l&#39;équipe comprenne facilement l&#39;objectif de la branche.</p><p>Exemple de nommage de branche :</p><ul><li><code>feature/ajout-nouvelle-fonctionnalite</code></li><li><code>bugfix/correction-texte-erreur</code></li></ul><h2 id="apporter-des-modifications-et-ajouter-des-commits" tabindex="-1">Apporter des modifications et ajouter des commits <a class="header-anchor" href="#apporter-des-modifications-et-ajouter-des-commits" aria-label="Permalink to &quot;Apporter des modifications et ajouter des commits&quot;">​</a></h2><p>Une fois la branche créée, vous pouvez commencer à travailler. Ajoutez, modifiez ou supprimez des fichiers. À chaque petite étape importante, vous devez enregistrer vos changements en ajoutant un <strong>commit</strong>.</p><p>Les <strong>commits</strong> permettent de suivre l&#39;évolution de votre travail. Chaque commit doit inclure un message clair expliquant ce qui a été modifié et pourquoi.</p><h3 id="pourquoi-les-messages-de-commit-sont-importants" tabindex="-1">Pourquoi les messages de commit sont importants ? <a class="header-anchor" href="#pourquoi-les-messages-de-commit-sont-importants" aria-label="Permalink to &quot;Pourquoi les messages de commit sont importants ?&quot;">​</a></h3><p>Ils permettent à tous les membres de l&#39;équipe de suivre les changements effectués, et de revenir à un point antérieur si nécessaire.</p><p>Exemple de message de commit :</p><ul><li><code>Ajout de la fonctionnalité d&#39;authentification utilisateur</code></li><li><code>Correction du bug lié au calcul du total des commandes</code></li></ul><h2 id="ouvrir-une-pull-request" tabindex="-1">Ouvrir une Pull Request <a class="header-anchor" href="#ouvrir-une-pull-request" aria-label="Permalink to &quot;Ouvrir une Pull Request&quot;">​</a></h2><p>Les <strong>Pull Requests</strong> (PR) sont au cœur de l&#39;utilisation de GitHub. Elles permettent de signaler aux autres membres de l&#39;équipe que vous avez des modifications prêtes à être examinées ou fusionnées dans la branche principale.</p><p>Une fois votre branche prête, vous ouvrez une PR. Cela permet aux autres de revoir votre code et de proposer des améliorations, ou de l’accepter pour qu&#39;il soit fusionné avec la branche principale.</p><h3 id="processus-de-pull-request" tabindex="-1">Processus de Pull Request : <a class="header-anchor" href="#processus-de-pull-request" aria-label="Permalink to &quot;Processus de Pull Request :&quot;">​</a></h3><ol><li>Ouvrir une PR pour signaler que des changements sont prêts à être examinés.</li><li>Inclure une description détaillée de ce qui a été fait.</li><li>Demander à d&#39;autres personnes de vérifier et de donner leur avis.</li></ol><h2 id="revue-des-modifications" tabindex="-1">Revue des modifications <a class="header-anchor" href="#revue-des-modifications" aria-label="Permalink to &quot;Revue des modifications&quot;">​</a></h2><p>Lorsque vous ouvrez une PR, il est temps pour les membres ayant accès au projet de réviser les modifications apportées.</p><p>Les <strong>Pull Requests</strong> favorisent la collaboration et permettent d’améliorer la qualité du code. C’est à ce moment que des discussions peuvent avoir lieu pour comprendre les choix effectués et proposer des améliorations.</p><h3 id="amelioration-continue" tabindex="-1">Amélioration continue : <a class="header-anchor" href="#amelioration-continue" aria-label="Permalink to &quot;Amélioration continue :&quot;">​</a></h3><p>Si vous recevez des retours sur votre PR, vous pouvez apporter des modifications supplémentaires en ajoutant de nouveaux commits. Ces nouveaux commits seront automatiquement intégrés à la PR pour une nouvelle revue.</p><p>Note : GitHub propose une vue unifiée de la PR qui montre les commits et les commentaires associés.</p><h2 id="deploiement" tabindex="-1">Déploiement <a class="header-anchor" href="#deploiement" aria-label="Permalink to &quot;Déploiement&quot;">​</a></h2><p>Une fois la PR revue et approuvée, il est temps de procéder au <strong>déploiement</strong>. Avant de fusionner définitivement dans la branche principale, GitHub permet de déployer à partir de la branche pour effectuer des tests en production.</p><p>Cela permet de s&#39;assurer que tout fonctionne correctement avant de finaliser l&#39;intégration des changements dans la branche principale.</p><h3 id="bonnes-pratiques" tabindex="-1">Bonnes pratiques : <a class="header-anchor" href="#bonnes-pratiques" aria-label="Permalink to &quot;Bonnes pratiques :&quot;">​</a></h3><ul><li>Utiliser des environnements de test dédiés pour déployer les branches avant la fusion.</li><li>Tester minutieusement toutes les fonctionnalités en production avant de valider la fusion.</li></ul><h2 id="fusionner" tabindex="-1">Fusionner <a class="header-anchor" href="#fusionner" aria-label="Permalink to &quot;Fusionner&quot;">​</a></h2><p>Une fois les tests effectués et que tout semble en ordre, vous pouvez fusionner votre branche dans la branche principale.</p><p>Les <strong>Pull Requests</strong> permettent de garder une trace de toutes les modifications apportées au code. Grâce à des commentaires et des noms de commits clairs, vous pouvez toujours comprendre les raisons des changements effectués, même après coup.</p><h3 id="astuce-pour-la-recherche" tabindex="-1">Astuce pour la recherche : <a class="header-anchor" href="#astuce-pour-la-recherche" aria-label="Permalink to &quot;Astuce pour la recherche :&quot;">​</a></h3><p>Vous pouvez ajouter des mots-clés à votre PR pour faciliter la recherche de changements spécifiques plus tard.</p><hr><h3 id="recapitulatif-du-processus-github-flow" tabindex="-1">Récapitulatif du processus GitHub Flow : <a class="header-anchor" href="#recapitulatif-du-processus-github-flow" aria-label="Permalink to &quot;Récapitulatif du processus GitHub Flow :&quot;">​</a></h3><ol><li><strong>Créez une branche</strong> pour chaque nouvelle fonctionnalité ou bug.</li><li><strong>Faites des commits</strong> régulièrement pour enregistrer vos progrès.</li><li><strong>Ouvrez une Pull Request</strong> pour permettre à d’autres de revoir vos modifications.</li><li><strong>Revoyez et discutez</strong> des changements avec votre équipe.</li><li><strong>Déployez</strong> la branche pour tester les modifications en production.</li><li><strong>Fusionnez</strong> la branche dans la branche principale après les tests.</li></ol><p>En suivant ces étapes, vous pouvez travailler efficacement avec Git et GitHub tout en garantissant la qualité et la sécurité du code.</p>',48),s=[i];function n(u,l,c,d,p,m){return o(),t("div",null,s)}const v=e(a,[["render",n]]);export{f as __pageData,v as default};
